import numpy as np

def solve_f_improved():
    # Solve 729u^3 - 594u^2 + 129u - 4 = 0
    coeffs = [729, -594, 129, -4]
    roots = np.roots(coeffs)

    min_f = float('inf')
    for u in roots:
        if np.isreal(u) and u >= 0:
            u_val = u.real
            x_val = np.sqrt(u_val)
            z_sq = 1 - 2 * u_val
            if z_sq >= 0:
                z_val = np.sqrt(z_sq)
                for sx in [1, -1]:
                    for sz in [1, -1]:
                        x = sx * x_val
                        z = sz * z_val
                        if abs(27*x**2 - 11 + 2*z/x) < 1e-6:
                            f = 9*x*x*z - 2*(2*x + z)
                            min_f = min(min_f, f)
                            print(f"Found f = {f} at (x,y,z) = ({x}, {x}, {z})")
    return min_f

print(f"Min f: {solve_f_improved()}")
